sys_script_include.script:
var OnboardingUtils = Class.create();
OnboardingUtils.prototype = {
    initialize: function() {
    },

    /**
     * P3-T01.1: Validates that critical fulfillment fields are filled.
     * @param {GlideRecord} grRequest - The current onboarding request record.
     * @return {Boolean} true if valid, false otherwise.
     */
    validateRequest: function(grRequest) {
    if (!grRequest.assignment_group ||
        !grRequest.due_date) {
        return false;
    }
    return true;
},

    /**
     * P3-T01.2: Returns the correct assignment group based on the category string.
     * @param {String} category - The category value from the request record.
     * @return {String} The sys_id of the target user group.
     */
    getAssignmentGroup: function(category) {
        var groups = {
            "equipment": "8a5055c9c61122780043563ef53438e3", 
            "system_access": "287ebd7da9fe198100f92cc8d1d2154e",
            "general": "d625dccec0a8016700a222a0f7900d06"
        };

        return groups[category] || groups["general"];
    },

    /**
     * P3-T01.3: Writes an audit tracking entry directly to the record's Work Notes.
     * @param {GlideRecord} grRequest - The target request record.
     * @param {String} action - Description of what occurred (e.g., "Approved & Fulfilled").
     */
    logAction: function(grRequest, action) {
        if (!grRequest) return;

        // Appends a clean, automated track entry into the activity journal logs
        grRequest.work_notes = "Launchpad Audit Log - Action executed: " + action;
    },

    type: 'OnboardingUtils'
};
